import sys


def merge_record(edits):
    """edits: (device, timestamp, field, value) from phones that were offline, in any order. For the field 'vaccines' the value is a comma-separated list and the result is the union of all lists, sorted. For every other field the latest timestamp wins; on a tie the larger device id wins. Return {field: value} with fields in sorted order."""
    latest, vaccines = {}, set()
    for device, ts, field, value in edits:
        if field == "vaccines":
            vaccines.update(v for v in value.split(",") if v)      # merge, never overwrite
        elif field not in latest or (ts, device) > latest[field][:2]:
            latest[field] = (ts, device, value)                     # last writer wins
    merged = {f: v for f, (_, _, v) in latest.items()}
    if any(field == "vaccines" for _, _, field, _ in edits):
        merged["vaccines"] = ",".join(sorted(vaccines))
    return dict(sorted(merged.items()))


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    edits = []
    for i in range(n):
        device, ts, field, value = data[1 + i].split()
        edits.append((device, int(ts), field, value))
    for field, value in merge_record(edits).items():
        print(field, value)


main()
